-- V59__update_invoice_extraction_schema_detailed.sql
-- Replace INVOICE extraction schema with detailed field descriptions for all extended metadata fields.
-- Follows the format established in V51__update_invoice_extraction_tax_line_items.sql.

UPDATE llm_prompts SET
    system_prompt = 'You are extracting structured metadata from a German invoice (Eingangsrechnung) or credit note (Gutschrift). Return ONLY a valid JSON object. Use null for any field you cannot find. Do NOT guess or infer values — only extract what is explicitly written on the document. Amounts must be numbers (not strings). Dates must be in yyyy-MM-dd format. IBAN must have all spaces removed. For credit notes, set invoiceType to the appropriate type and populate draweeNo with the original invoice number being credited.',
    extraction_schema = '{
  "vendorName": "string or null — The company or person who issued the invoice. Look for company names with GmbH, AG, KG, e.K., e.V., OHG, UG, or a personal name at the top of the document.",
  "invoiceNumber": "string or null — The invoice reference number (Rechnungsnummer, Rechnungs-Nr., Re-Nr., Beleg-Nr.). This is NOT a date. It is typically an alphanumeric code like RE-2025-001, 12345, INV-0042, 0/0/0502/000338.",
  "invoiceDate": "string or null — The date the invoice was issued (Rechnungsdatum, Belegdatum, Datum). Format: yyyy-MM-dd.",
  "dueDate": "string or null — Payment due date (Fälligkeitsdatum, Zahlbar bis, Zahlungsziel). Format: yyyy-MM-dd. null if not stated.",
  "invoiceType": "string or null — The type of invoice. One of: Rechnung, Gutschrift § 14 UStG, Gutschrift/Rechnungskorrektur, Rechnungskorrektur, Abschlagsrechnung, Schlussrechnung, Bargutschrift, Barrechnung, Barrechnungskorrektur. For credit notes (Gutschriften) and credit note corrections (Gutschrift/Rechnungskorrektur), set this field accordingly.",
  "draweeNo": "string or null — For credit notes only: the original invoice number (Originalrechnungsnummer) this credit note refers to. Also called Gutschriftreferenz, Belegreferenz. null for regular invoices.",
  "orderId": "string or null — Order reference number (Bestellnummer, Bestell-Nr., Referenz-Nr.) if shown on the invoice.",
  "currency": "string or null — Currency code. Default EUR if not explicitly stated.",
  "iban": "string or null — The IBAN for payment. Remove ALL spaces (e.g. DE78840550500012032050).",
  "paymentReference": "string or null — Payment reference or purpose (Verwendungszweck, Zahlungsreferenz, Betreff).",
  "supplierCity": "string or null — The vendor PLZ and city (e.g. 40235 Düsseldorf, 80331 München). MUST include the postal code.",
  "supplierStreet": "string or null — The vendor street address including house number (e.g. Musterstraße 123, Hauptstraße 45a).",
  "supplierZip": "string or null — The vendor postal code (PLZ) alone, e.g. 80331.",
  "supplierCountry": "string or null — The vendor country as 2-letter ISO code (e.g. DE, AT, CH, NL).",
  "supplierPhone": "string or null — The vendor phone number (Telefon, Tel., Fon).",
  "supplierEmail": "string or null — The vendor email address (E-Mail, Email).",
  "vatId": "string or null — VAT identification number (USt-IdNr., USt-Id, UID, VAT ID). Format like DE123456789.",
  "shipToCountry": "string or null — Destination country for OSS/VAT purposes (Lieferland, Bestimmungsland) as 2-letter ISO code. null if same as supplier country.",
  "shipFromCountry": "string or null — Origin country for cross-border OSS deliveries (Herkunftsland) as 2-letter ISO code. null for domestic invoices.",
  "deliveryDate": "string or null — Delivery or service date (Lieferdatum, Leistungsdatum). Format: yyyy-MM-dd. Single date for one-time deliveries.",
  "deliveryDateStart": "string or null — Service period start date (Leistungszeitraum von, Lieferzeitraum von) for ongoing deliveries. Format: yyyy-MM-dd. null if not a period.",
  "deliveryDateEnd": "string or null — Service period end date (Leistungszeitraum bis, Lieferzeitraum bis) for ongoing deliveries. Format: yyyy-MM-dd. null if not a period.",
  "netAmount": "number or null — Total net amount (Nettobetrag, Netto summe) before tax. Sum of all line items net.",
  "grossAmount": "number or null — Total gross amount (Bruttobetrag, Gesamtbetrag) including tax. The final amount due.",
  "taxAmount": "number or null — Total tax amount (Steuerbetrag, MwSt.-Betrag). Sum of all tax.",
  "taxRate": "number or null — Single tax rate percentage if all items have the same rate (e.g. 19, 7). null for split-tax invoices.",
  "accountNo": "string or null — G/L account number / Gegenkonto (e.g. 4400, 6000). The expense or asset account for booking.",
  "bpAccountNo": "string or null — Creditor account number / Kreditorenkonto (e.g. 70000). The business partner account in DATEV.",
  "bookingText": "string or null — Short German booking text (Buchungstext) max 60 characters. A concise description like Büromaterial or IT-Dienstleistung.",
  "paymentConditionsText": "string or null — Payment conditions text (Zahlungsbedingungen, Zahlungskonditionen). Free-text description of payment terms if present.",
  "paidAt": "string or null — Date the invoice was marked as paid (Bezahlt am, Zahlungsdatum). Format: yyyy-MM-dd. null if unpaid.",
  "paymentDunningBlock": "boolean — true if payment is blocked (Zahlungssperre, Mahnstopp) or the invoice is marked as not payable.",
  "costCategoryId": "string or null — Cost category 1 / Kost1 (e.g. 001, 0100). A cost center or cost category identifier for internal accounting.",
  "costCategoryId2": "string or null — Cost category 2 / Kost2. A secondary cost category identifier.",
  "costAmount": "number or null — The amount allocated to the cost category / Kostenbetrag.",
  "exchangeRate": "number or null — Exchange rate (Wechselkurs) for foreign currency invoices. 6 decimal places. null for EUR invoices.",
  "euTaxRate": "number or null — EU cross-border tax rate (EU-Steuersatz) for OSS/VAT due on EU distance sales. e.g. 19, 21.",
  "buCode": "string or null — Business transaction key / BU-Schlüssel (2 digits, e.g. 01, 04, 09). DATEV business transaction identifier.",
  "typeOfReceivable": "string or null — Type of receivable / Forderungsart (e.g. Miete, Pacht, Lieferung, Dienstleistung).",
  "lineItems": "array or null — All individual items/positions on the invoice. Extract each row from the item table: [{\"position\": \"string or null (Pos., Nr.)\", \"description\": \"string (Bezeichnung, Beschreibung, Artikel)\", \"quantity\": number or null (Menge, Anzahl, Stk. — pay attention to units like 24 Fl., 20er Kasten)\", \"unit\": \"string or null (Einheit: Stk., Std., Pausch., kg, m, Fl., KA, KI)\", \"unitPrice\": number or null (Einzelpreis, Preis/Einheit)\", \"netProductPrice\": number or null (Einzelpreis netto, Productpreis ohne MwSt.)\", \"grossProductPrice\": number or null (Einzelpreis brutto, Productpreis inkl. MwSt.)\", \"productId\": \"string or null (Artikelnr., EAN,Artikelnummer)\", \"deliveryNoteId\": \"string or null (Lieferscheinnummer)\", \"netAmount\": number or null (Netto, Betrag)\", \"taxRate\": number or null (MwSt. %)\", \"taxAmount\": number or null (Steuerbetrag)\", \"grossAmount\": number or null (Brutto)\", \"taxExemptionReason\": \"string or null (Steuerbefreiung Grund, z.B. §4 Nr. 1b UStG)\", \"accountingInfo\": {\"accountNo\": \"string or null (Gegenkonto)\", \"costCategoryId\": \"string or null (Kost1)\", \"costCategoryId2\": \"string or null (Kost2)\"}}]. Include every line item even if some fields are missing.",
  "taxLineItems": "array — Steueraufschlüsselung / MwSt.-Aufstellung. ALWAYS extract at least one entry, even for single tax rate invoices. For each tax rate on the invoice: [{\"description\": \"string or null — Bezeichnung (z.B. Speisen, Getränke, Waren 19%, Lieferung 7%)\", \"netAmount\": number — Nettobetrag (Betrag ohne MwSt.)\", \"taxRate\": number — MwSt.-Satz in Prozent (e.g. 0, 7, 19)\", \"taxAmount\": number — MwSt.-Betrag / Steuerbetrag\", \"grossAmount\": number — Bruttobetrag (Betrag inkl. MwSt.)\"}].",
  "paymentDetails": "array or null — ALL payment methods and amounts used to pay the invoice. Many invoices use multiple payment methods (e.g. deposit credit + cash). Extract each: [{\"method\": \"string (Überweisung, Bar, EC-Karte, Leergutguthaben, Kreditkarte, Lastschrift, Verrechnung, Gutschein)\", \"amount\": number (the amount paid via this method), \"description\": \"string or null (additional info like Leergutguthaben, Rückgeld, Restguthaben)\"}]. For deposit/Leergut invoices, include: the deposit credit used, the invoice amount deducted, and any change/Rückgeld returned.",
  "discountTerms": "array or null — Cash discount / Skonto terms if mentioned. Extract each: [{\"percentage\": number (e.g. 2, 3), \"days\": number or null (days to pay for discount), \"amount\": number or null (discounted amount)\", \"description\": \"string or null (description)}\"]. null if no discount terms.",
  "additionalInfo": "array or null — Additional information fields (Weitere Angaben) that do not fit other categories. Extract each: [{\"type\": \"string (the label or category, e.g. Versandkosten, Bearbeitungsgebühr, Nachlass)\", \"content\": \"string (the value or description)\"}].",
  "taxExemptionReason": "string or null — Reason for tax exemption if the invoice or items are tax-exempt (Steuerbefreiung, Befreiung von MwSt.). E.g. §4 Nr. 1b UStG, Kleinunternehmerregelung §19 UStG."
}',
    updated_at = CURRENT_TIMESTAMP
WHERE document_type = 'INVOICE';
